#include "PETScNonlinearPoisson.h"
#include "Convergence.h"
#include <chrono>
#include <iostream>
int main(int argc,char** argv) {
 if(PetscInitialize(&argc,&argv,nullptr,nullptr)) return 1;
 ::testing::InitGoogleTest(&argc,argv);
 {
 using namespace Rodin; using namespace Rodin::Tests::Convergence;
 auto geometry=Geometry::Polytope::Type::Pyramid;
 if(argc>1 && std::string(argv[1])=="Tetrahedron") geometry=Geometry::Polytope::Type::Tetrahedron;
 if(argc>1 && std::string(argv[1])=="Hexahedron") geometry=Geometry::Polytope::Type::Hexahedron;
 auto mesh=UniformGrid(geometry).makeMesh(argc>2 ? std::stoul(argv[2]) : 3);
 const auto start=std::chrono::steady_clock::now();
 PETScNonlinearPoissonProblem<4,decltype(mesh)> problem(mesh,16);
 auto errors=problem.solve(1e-11,18,[](const auto&,const auto&){});
 std::cout.precision(17); std::cout<<"ERRORS "<<errors.getL2()<<" "<<errors.getH1Seminorm()<<" SECONDS "<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<std::endl;
 }
 bool failed=::testing::Test::HasFailure();
 return PetscFinalize()?1:failed;
}

