#include "PETScStokesTractionProblem.h"
#include "Convergence.h"
#include <chrono>
#include <iostream>
int main(int argc,char** argv) {
 if(PetscInitialize(&argc,&argv,nullptr,nullptr)) return 1;
 ::testing::InitGoogleTest(&argc,argv);
 {
 using namespace Rodin; using namespace Rodin::Tests::Convergence;
 auto mesh=UniformGrid(Geometry::Polytope::Type::Pyramid).makeMesh(3);
 using Problem=PETScStokesTractionProblem<decltype(mesh)>;
 UnitBoxBoundary::labelCoordinatePartition(mesh,0,Problem::DirichletAttribute,Problem::TractionAttribute,Problem::TractionAttribute);
 const StokesData data(mesh.getDimension(),StokesData::Field::Quartic,1,2);
 const auto start=std::chrono::steady_clock::now();
 auto result=Problem(mesh,data).solve<3>();
 std::cout.precision(17);std::cout<<"STOKES "<<result.fields.velocity.getL2()<<" "<<result.fields.velocity.getH1Seminorm()<<" "<<result.fields.pressure.getL2()<<" SECONDS "<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<std::endl;
 }
 bool failed=::testing::Test::HasFailure(); return PetscFinalize()?1:failed;
}

drivers.matrix-kernels:
#include "Rodin/Math/SpatialMatrix.h"
#include <chrono>
#include <ctime>
#include <iostream>
#include <string>
using namespace Rodin;
using Matrix = Math::SpatialMatrix<Real>;
template<class Kernel> void run(Kernel kernel, int rows, int columns) {
 Matrix a(rows,columns),b(rows,columns);
 for(int j=0;j<columns;++j) for(int i=0;i<rows;++i) {a(i,j)=Real(1+i+j)/7; b(i,j)=Real(2+i+2*j)/11;}
 double total=0;const auto start=std::clock();
 for(size_t i=0;i<1000000;++i) {
  asm volatile("" : "+m"(a), "+m"(b));
  total+=kernel(a,b);
 }
 std::cout.precision(17); std::cout<<double(std::clock()-start)/CLOCKS_PER_SEC<<" "<<total<<std::endl;
}
int main(int argc,char**argv) {
 const std::string mode=argc>1?argv[1]:"direct"; const int rows=argc>2?std::stoi(argv[2]):3;const int columns=argc>3?std::stoi(argv[3]):3;
 if(mode=="direct") run([](const Matrix&a,const Matrix&b){return Math::dot(a,b);},rows,columns);
 else if(mode=="original") run([](const Matrix&a,const Matrix&b){return Math::dot(a.getData().topLeftCorner(a.rows(),a.cols()),b.getData().topLeftCorner(b.rows(),b.cols()));},rows,columns);
 else if(mode=="map") run([](const Matrix&a,const Matrix&b){using Storage=Eigen::Matrix<Real,Eigen::Dynamic,Eigen::Dynamic,Eigen::ColMajor,3,3>;using View=Eigen::Map<const Storage,Eigen::Unaligned,Eigen::OuterStride<3>>;return Math::dot(View(a.getData().data(),a.rows(),a.cols()),View(b.getData().data(),b.rows(),b.cols()));},rows,columns);
 else if(mode=="unrolled") run([](const Matrix&a,const Matrix&b){const auto column=[&](size_t j){const auto*left=a.getData().data()+3*j;const auto*right=b.getData().data()+3*j;switch(a.rows()){case 1:return left[0]*right[0];case 2:return left[0]*right[0]+left[1]*right[1];case 3:return left[0]*right[0]+left[1]*right[1]+left[2]*right[2];default:return Real(0);}};switch(a.cols()){case 1:return column(0);case 2:return column(0)+column(1);case 3:return column(0)+column(1)+column(2);default:return Real(0);}},rows,columns);
}
